package dev.mixer.android;
import java.util.*;import android.view.inputmethod.*;
/** Exact fields/types/order/value oracles; later object mutation cannot rewrite recorded evidence. */
public final class TypedSnapshotControls {
 private TypedSnapshotControls(){}private static int checks;
 private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 private static Map<String,Object> snapshot(Object value){return Json.object(OutcomeCapture.actual(value));}
 private static List<Object> fields(Object value){return Json.array(snapshot(value).get("fields"));}
 private static void expect(List<Object> fields,int at,String name,String type,Object value){Map<String,Object> field=Json.object(fields.get(at));check(field.keySet().equals(new LinkedHashSet<>(List.of("field","type","value"))),"exact typed field schema");check(field.get("field").equals(name)&&field.get("type").equals(type)&&Objects.equals(field.get("value"),value),"exact field/type/order/value "+name);}
 public static void main(String[] args){
  android.text.Editable editable=new android.text.Editable("hello");Object span=new Object();editable.setSpan(span,1,4,7);Map<String,Object> captured=snapshot(editable);List<Object> ef=Json.array(captured.get("fields"));expect(ef,0,"text","java.lang.String","hello");Map<String,Object> spanField=Json.object(ef.get(1));check(spanField.get("field").equals("spans")&&spanField.get("type").equals("ordered-span-records"),"span field ordered type");List<Object> spans=Json.array(spanField.get("value"));List<Object> one=Json.array(spans.get(0));expect(one,0,"object","identity",DirectBoundaryStates.identity(span));expect(one,1,"start","int",1);expect(one,2,"end","int",4);expect(one,3,"flags","int",7);editable.replace(0,5,"changed");editable.removeSpan(span);expect(ef,0,"text","java.lang.String","hello");check(Json.array(spanField.get("value")).size()==1,"span evidence copied at return instant");
  ExtractedText extracted=new ExtractedText();extracted.text=new android.text.Editable("before");extracted.startOffset=2;extracted.partialStartOffset=3;extracted.partialEndOffset=6;extracted.selectionStart=4;extracted.selectionEnd=5;extracted.flags=9;List<Object> xf=fields(extracted);String[] names={"text","startOffset","partialStartOffset","partialEndOffset","selectionStart","selectionEnd","flags"};Object[] values={"before",2,3,6,4,5,9};for(int i=0;i<names.length;i++)expect(xf,i,names[i],i==0?"java.lang.CharSequence:string":"int",values[i]);((android.text.Editable)extracted.text).clear();extracted.selectionEnd=99;expect(xf,0,"text","java.lang.CharSequence:string","before");expect(xf,5,"selectionEnd","int",5);
  android.text.Editable surroundingText=new android.text.Editable("original");SurroundingText surrounding=new SurroundingText(surroundingText,2,3,7);List<Object> sf=fields(surrounding);expect(sf,0,"text","java.lang.CharSequence:string","original");expect(sf,1,"start","int",2);expect(sf,2,"end","int",3);expect(sf,3,"offset","int",7);TextSnapshot nested=new TextSnapshot(surrounding);List<Object> nf=fields(nested);Map<String,Object> text=Json.object(nf.get(0));check(text.get("field").equals("text")&&text.get("type").equals("android.view.inputmethod.SurroundingText"),"nested exact field/type");List<Object> nestedFields=Json.array(Json.object(text.get("value")).get("fields"));surroundingText.clear();expect(nestedFields,0,"text","java.lang.CharSequence:string","original");
  OutcomeCapture dirty=new OutcomeCapture();dirty.begin();NativeOutcomeProbe.captureFailed(new AssertionError("owned evidence failure"));dirty.end();check(!dirty.clean(),"dirty attempt latched");OutcomeCapture next=new OutcomeCapture();next.begin();next.end();check(next.clean()&&!dirty.clean(),"next begin cannot erase earlier dirty attempt");check(ConcreteHostProbe.events().isEmpty(),"snapshot controls are passive and have zero native callbacks");System.out.println("PASS typed snapshot/latch controls checks="+checks);
 }
}
